/* Linker version script for libnb-trtinfer.so: export the extern "C" API and
   nothing else. -fvisibility=hidden alone is not enough: libstdc++ declares
   namespace std with default visibility, so template instantiations (e.g.
   std::vector growth) would be exported and could interpose on the
   process's own libstdc++. */
{
  global: nb_*;
  local: *;
};
